import json
import requests
from datetime import datetime

employees = []


def add_employee(name, age, salary, department):
    employee = {
        "id": len(employees) + 1,
        "name": name,
        "age": age,
        "salary": salary,
        "department": department,
        "joined": datetime.now()
    }

    employees.append(employee)
    return employee


def find_employee(employee_id):
    for employee in employees:
        if employee["id"] == employee_id:
            return employee

    return None


def update_salary(employee_id, new_salary):
    employee = find_employee(employee_id)

    if employee:
        employee["salary"] = new_salary
        print("Salary updated")
    else:
        print("Employee not found")


def calculate_yearly_salary(employee):
    return employee["salary"] * 12


def calculate_bonus(employee):
    if employee["department"] == "IT":
        return employee["salary"] * 20
    elif employee["department"] == "HR":
        return employee["salary"] * 15
    else:
        return employee["salary"] * 10


def search_employees(keyword):
    result = []

    for employee in employees:
        if keyword.lower() in employee["name"].lower():
            result.append(employee)

        if keyword.lower() in employee["department"].lower():
            result.append(employee)

    return result


def remove_employee(employee_id):
    employee = find_employee(employee_id)

    if employee:
        employees.remove(employee)
        print("Employee deleted")
    else:
        print("Employee not found")


def save_employees(filename):
    try:
        with open(filename, "w") as file:
            json.dump(employees, file)
        print("Employees saved")
    except:
        print("Unable to save employees")


def load_employees(filename):
    global employees

    try:
        with open(filename, "r") as file:
            employees = json.load(file)

        print("Employees loaded")

    except FileNotFoundError:
        print("File does not exist")


def get_employee_data(employee_id):
    employee = find_employee(employee_id)

    if employee:
        return {
            "name": employee["name"],
            "salary": employee["salary"],
            "bonus": calculate_bonus(employee),
            "yearly_salary": calculate_yearly_salary(employee)
        }

    return {}


def get_exchange_rate():
    response = requests.get(
        "https://api.exchangerate-api.com/v4/latest/USD"
    )

    if response.status_code == 200:
        return response.json()["rates"]["INR"]

    return None


def convert_salary(employee_id):
    employee = find_employee(employee_id)

    if employee:
        rate = get_exchange_rate()

        if rate:
            return employee["salary"] * rate

    return 0


def generate_report():
    report = ""

    for employee in employees:
        report += "Employee: " + employee["name"] + "\n"
        report += "Department: " + employee["department"] + "\n"
        report += "Salary: " + str(employee["salary"]) + "\n"
        report += "Bonus: " + str(calculate_bonus(employee)) + "\n"
        report += "----------------------\n"

    return report


def get_average_salary():
    total = 0

    for employee in employees:
        total += employee["salary"]

    return total / len(employees)


def promote_employee(employee_id, percentage):
    employee = find_employee(employee_id)

    if employee:
        employee["salary"] = employee["salary"] + (
            employee["salary"] * percentage
        )

        return True

    return False


def get_department_employees(department):
    result = []

    for employee in employees:
        if employee["department"] == department:
            result.append(employee)

    return result


def print_high_salary_employees(limit):
    for employee in employees:
        if employee["salary"] > limit:
            print(
                employee["name"],
                employee["salary"]
            )


